package org.apache.parquet.filter2;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import org.apache.parquet.filter2.IncrementallyUpdatedFilterPredicateGenerator;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

public class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @Test
  void testGeneratedCodeStructure(@TempDir Path tempDir) throws IOException {
    Path outPath = tempDir.resolve("org/apache/parquet/filter2/recordlevel/IncrementallyUpdatedFilterPredicateBuilder.java");
    Files.createDirectories(outPath.getParent());
    File outFile = outPath.toFile();

    IncrementallyUpdatedFilterPredicateGenerator generator = new IncrementallyUpdatedFilterPredicateGenerator(outFile);
    generator.run();

    String content = Files.readString(outPath);

    // The generated file should start with the correct package declaration
    assertTrue(content.startsWith("package org.apache.parquet.filter2.recordlevel;"),
        "Generated file should start with the package declaration");

    // The generated class declaration must be present
    assertTrue(content.contains("public class IncrementallyUpdatedFilterPredicateBuilder extends IncrementallyUpdatedFilterPredicateBuilderBase"),
        "Generated file should declare the IncrementallyUpdatedFilterPredicateBuilder class extending the base");

    // The generator should create visit methods for Eq predicates
    assertTrue(content.contains("visit(Eq<T> pred)"), "Generated file should contain Eq visit method for predicates");

    // Contains-related structures should be generated (ContainsPredicate inner types present)
    assertTrue(content.contains("ContainsPredicate") || content.contains("class ContainsPredicate"),
        "Generated file should include Contains related predicates and classes");

    // The file should end with a closing brace of the class
    assertTrue(content.trim().endsWith("}"), "Generated file should end with a closing class brace");
  }

}

